CSS IMPLEMENTATION SIGNALS

:root {
  color-scheme: dark;
  --bg: #06080d;
  --panel: #10151f;
  --line: rgba(255,255,255,.14);
  --text: #f6f8fb;
  --muted: #a9b3c3;
  --blue: #69a7ff;
  --green: #72f0b4;
  --gold: #ffd36a;
}

* { box-sizing: border-box; }
html { background: var(--bg); }
body {
  margin: 0;
  min-height: 100vh;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--text);
  background:
    linear-gradient(120deg, rgba(105,167,255,.16), transparent 34%),
    linear-gradient(180deg, #06080d 0%, #0a1018 45%, #07090f 100%);
}

a { color: inherit; text-decoration: none; }

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 18px clamp(18px, 4vw, 46px);
  border-bottom: 1px solid var(--line);
  background: rgba(6,8,13,.82);
  backdrop-filter: blur(18px);
  position: sticky;
  top: 0;
  z-index: 5;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.brand img {
  width: 38px;
  height: 38px;
  object-fit: contain;
}

.brand span,
.brand small { display: block; }
.brand strong { font-size: 1rem; letter-spacing: 0; }
.brand small { color: var(--muted); font-size: .78rem; margin-top: 2px; }

nav {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

nav a,
.actions a,
.token-panel button,
.deploy-form button,
.item-actions button,
.transfer-select {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 13px;
  color: var(--text);
  background: rgba(255,255,255,.055);
  font-size: .9rem;
}

.actions .primary,
.token-panel button,
.deploy-form button,
.item-actions button {
  background: var(--blue);
  border-color: var(--blue);
  color: #031124;
  font-weight: 700;
}

.item-actions button:disabled {
  cursor: progress;
  opacity: .64;
}

.transfer-select {
  min-height: 40px;
  max-width: 190px;
  color: var(--text);
  background: #080b11;
  cursor: pointer;
}

main { width: min(1180px, calc(100% - 32px)); margin: 0 auto; }

.hero {
  min-height: 76vh;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(300px, .72fr);
  align-items: center;
  gap: clamp(24px, 5vw, 64px);
  padding: clamp(48px, 9vw, 112px) 0 40px;
}

.eyebrow {
  margin: 0 0 12px;
  color: var(--green);
  text-transform: uppercase;
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .08em;
}

h1,
h2 {
  margin: 0;
  letter-spacing: 0;
  line-height: .98;
}

h1 { font-size: clamp(3rem, 8vw, 7.4rem); max-width: 900px; }
h2 { font-size: clamp(2rem, 4vw, 4.2rem); }

.lede {
  max-width: 720px;
  color: var(--muted);
  font-size: clamp(1rem, 1.8vw, 1.26rem);
  line-height: 1.6;
}

.actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }

.signal-board,
.status-panel,
.token-panel,
.surface {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(16,21,31,.78);
  box-shadow: 0 28px 70px rgba(0,0,0,.28);
}

.signal-board { padding: 16px; display: grid; gap: 12px; }
.signal-board div {
  display: grid;
  gap: 6px;
  padding: 15px;
  background: rgba(255,255,255,.045);
  border-radius: 8px;
}
.signal-board span,
.surface span,
.token-panel span { color: var(--muted); font-size: .78rem; text-transform: uppercase; font-weight: 800; }
.signal-board strong { font-size: 1rem; overflow-wrap: anywhere; }

.band { padding: 54px 0; border-top: 1px solid var(--line); }
.surface-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 22px;
}
.surface {
  display: grid;
  gap: 10px;
  padding: 18px;
  min-height: 178px;
}
.surface strong { font-size: 1.28rem; }
.surface small { color: var(--muted); line-height: 1.5; }

.two {
  display: grid;
  grid-template-columns: minmax(0, .8fr) minmax(0, 1fr);
  gap: 20px;
  align-items: center;
}
.flow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
.flow span {
  min-height: 92px;
  display: grid;
  place-items: center;
  text-align: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255,255,255,.045);
  padding: 12px;
}

.custody-copy {
  display: grid;
  gap: 12px;
  color: var(--muted);
  line-height: 1.65;
}

.custody-copy p { margin: 0; }
.custody-copy code { color: var(--gold); }

.guide-hero {
  min-height: 70vh;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, .5fr);
  align-items: center;
  gap: clamp(22px, 5vw, 56px);
  padding: clamp(48px, 8vw, 96px) 0 38px;
}

.guide-card,
.price-card,
.step-grid article,
.code-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(16,21,31,.78);
  box-shadow: 0 28px 70px rgba(0,0,0,.24);
}

.guide-card {
  display: grid;
  gap: 12px;
  padding: 20px;
}

.guide-card span,
.price-card span,
.step-grid span {
  color: var(--green);
  font-size: .76rem;
  font-weight: 800;
  text-transform: uppercase;
}

.guide-card strong {
  overflow-wrap: anywhere;
  font-size: 1.1rem;
}

.guide-card small,
.boundary-note {
