.list-item strong {
  overflow-wrap: anywhere;
}
.list-panel {
  display: grid;
  gap: 10px;
  margin-top: 14px;
  color: var(--muted);
}
.list-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 14px;
