}

a { color: inherit; text-decoration: none; }

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 18px clamp(18px, 4vw, 46px);
  border-bottom: 1px solid var(--line);
  background: rgba(6,8,13,.82);
  backdrop-filter: blur(18px);
  position: sticky;
  top: 0;
  z-index: 5;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.brand img {
  width: 38px;
  height: 38px;
  object-fit: contain;
}

.brand span,
.brand small { display: block; }
.brand strong { font-size: 1rem; letter-spacing: 0; }
.brand small { color: var(--muted); font-size: .78rem; margin-top: 2px; }

nav {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

nav a,
.actions a,
.token-panel button,
.deploy-form button,
.item-actions button,
.transfer-select {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 13px;
  color: var(--text);
  background: rgba(255,255,255,.055);
  font-size: .9rem;
}

.actions .primary,
.token-panel button,
.deploy-form button,
.item-actions button {
  background: var(--blue);
  border-color: var(--blue);
  color: #031124;
  font-weight: 700;
}

.item-actions button:disabled {
  cursor: progress;
  opacity: .64;
}

.transfer-select {
  min-height: 40px;
  max-width: 190px;
  color: var(--text);
  background: #080b11;
  cursor: pointer;
}

main { width: min(1180px, calc(100% - 32px)); margin: 0 auto; }

.hero {
  min-height: 76vh;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(300px, .72fr);
  align-items: center;
  gap: clamp(24px, 5vw, 64px);
  padding: clamp(48px, 9vw, 112px) 0 40px;
}

.eyebrow {
  margin: 0 0 12px;
  color: var(--green);
  text-transform: uppercase;
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .08em;
}

h1,
h2 {
  margin: 0;
  letter-spacing: 0;
  line-height: .98;
}

h1 { font-size: clamp(3rem, 8vw, 7.4rem); max-width: 900px; }
h2 { font-size: clamp(2rem, 4vw, 4.2rem); }

.lede {
  max-width: 720px;
  color: var(--muted);
  font-size: clamp(1rem, 1.8vw, 1.26rem);
  line-height: 1.6;
}

.actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 28px; }

.signal-board,
.status-panel,
.token-panel,
.surface {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(16,21,31,.78);
  box-shadow: 0 28px 70px rgba(0,0,0,.28);
}

.signal-board { padding: 16px; display: grid; gap: 12px; }
.signal-board div {
  display: grid;
  gap: 6px;
  padding: 15px;
  background: rgba(255,255,255,.045);
  border-radius: 8px;
}
.signal-board span,
.surface span,
.token-panel span { color: var(--muted); font-size: .78rem; text-transform: uppercase; font-weight: 800; }
.signal-board strong { font-size: 1rem; overflow-wrap: anywhere; }

.band { padding: 54px 0; border-top: 1px solid var(--line); }
.surface-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 22px;
}
.surface {
  display: grid;
  gap: 10px;
  padding: 18px;
  min-height: 178px;
}
.surface strong { font-size: 1.28rem; }
.surface small { color: var(--muted); line-height: 1.5; }

.two {
  display: grid;
  grid-template-columns: minmax(0, .8fr) minmax(0, 1fr);
  gap: 20px;
  align-items: center;
}
.flow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}
.flow span {
  min-height: 92px;
  display: grid;
  place-items: center;
  text-align: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255,255,255,.045);
  padding: 12px;
}

.custody-copy {
  display: grid;
  gap: 12px;
  color: var(--muted);
  line-height: 1.65;
}

.custody-copy p { margin: 0; }
.custody-copy code { color: var(--gold); }

.guide-hero {
  min-height: 70vh;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, .5fr);
  align-items: center;
  gap: clamp(22px, 5vw, 56px);
  padding: clamp(48px, 8vw, 96px) 0 38px;
}

.guide-card,
.price-card,
.step-grid article,
.code-panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(16,21,31,.78);
  box-shadow: 0 28px 70px rgba(0,0,0,.24);
}

.guide-card {
  display: grid;
  gap: 12px;
  padding: 20px;
}

.guide-card span,
.price-card span,
.step-grid span {
  color: var(--green);
  font-size: .76rem;
  font-weight: 800;
  text-transform: uppercase;
}

.guide-card strong {
  overflow-wrap: anywhere;
  font-size: 1.1rem;
}

.guide-card small,
.boundary-note {
  color: var(--muted);
  line-height: 1.55;
}

.guide-section { display: grid; gap: 22px; }
.section-heading { display: grid; gap: 8px; max-width: 820px; }

.step-grid,
.pricing-grid,
.feature-list {
  display: grid;
  gap: 14px;
}

.step-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }

.step-grid article {
  padding: 18px;
  display: grid;
  gap: 10px;
  min-height: 190px;
}

.step-grid h3,
.price-card h3 {
  margin: 0;
  line-height: 1.1;
}

.step-grid p,
.price-card p {
  color: var(--muted);
  line-height: 1.5;
  margin: 0;
}

.step-grid a {
  color: var(--gold);
  font-weight: 800;
}

.feature-list {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.feature-list span {
  min-height: 82px;
  display: grid;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255,255,255,.045);
  color: var(--text);
  padding: 16px;
}

.pricing-grid {
  grid-template-columns: repeat(5, minmax(190px, 1fr));
  align-items: stretch;
}

.price-card {
  display: grid;
  align-content: start;
  gap: 14px;
  padding: 18px;
}

.price-card h3 {
  font-size: clamp(1.35rem, 2.4vw, 2rem);
}

.price-card ul {
  display: grid;
  gap: 8px;
  padding-left: 18px;
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.price-card.reserve {
  border-color: rgba(255, 211, 106, .42);
  background: rgba(45, 36, 13, .44);
}

.code-panel {
  margin: 0;
  padding: 20px;
  color: #d7e8ff;
  overflow: auto;
  line-height: 1.6;
  white-space: pre-wrap;
}

.console-shell { padding: 70px 0; display: grid; gap: 18px; }
.console-grid,
.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(280px, .72fr) minmax(0, 1fr);
  gap: 14px;
  align-items: stretch;
}
.dashboard-grid {
  grid-template-columns: minmax(0, 1.12fr) minmax(260px, .72fr) minmax(260px, .72fr);
}
.token-panel { padding: 18px; display: grid; gap: 14px; max-width: 720px; }
.token-panel label,
.deploy-form label { display: grid; gap: 8px; }
.token-panel input,
.token-panel select,
.token-panel textarea,
.deploy-form input,
.deploy-form select,
.deploy-form textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  background: #080b11;
  color: var(--text);
}
.deploy-form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 14px;
}
.deploy-form span {
  color: var(--muted);
  font-size: .78rem;
  text-transform: uppercase;
  font-weight: 800;
}
.deploy-form .file-field {
  grid-column: span 3;
}
.token-panel .checkbox-line,
.deploy-form .checkbox-line {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  text-transform: none;
}
.token-panel .checkbox-line input,
.deploy-form .checkbox-line input {
  width: auto;
}
.token-panel button,
.deploy-form button { width: fit-content; cursor: pointer; }
.deploy-form button {
  align-self: end;
  min-height: 43px;
}
.status-panel progress {
  width: 100%;
  height: 12px;
  margin-top: 12px;
  accent-color: var(--green);
}
.status-panel { padding: 18px; min-width: 0; }
.status-panel h2 {
  font-size: clamp(1.25rem, 2vw, 2rem);
  line-height: 1.1;
}
.status-panel.wide { min-height: 280px; }
.mini-status {
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.metric-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 14px;
}
.metric-grid div,
.list-item {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255,255,255,.045);
}
.metric-grid div {
  display: grid;
  gap: 6px;
  padding: 13px;
}
.metric-grid span,
.list-item span {
  color: var(--muted);
  font-size: .72rem;
  font-weight: 800;
  text-transform: uppercase;
}
.metric-grid strong,
.list-item strong {
  overflow-wrap: anywhere;
}
.list-panel {
  display: grid;
  gap: 10px;
  margin-top: 14px;
  color: var(--muted);
}
.list-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 14px;
  color: var(--text);
}
.list-item.compact {
  grid-template-columns: 1fr;
  align-items: start;
}
.list-item div {
  display: grid;
  gap: 6px;
  min-width: 0;
}
.list-item small,
.list-item a {
  color: var(--muted);
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.list-item a:hover { color: var(--green); }
.item-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}
pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--muted);
  line-height: 1.5;
}

@media (max-width: 840px) {
  .topbar { align-items: flex-start; flex-direction: column; }
  nav { justify-content: flex-start; }
  .hero,
  .guide-hero,
  .two,
  .console-grid,
  .dashboard-grid { grid-template-columns: 1fr; min-height: auto; }
